CookieStore.write:
(data) => {
        const msPerHour = 60 * 60 * 1000;
        if (!window.cookieStore) {
          throw new Error('Unsupported');
        }
        window.cookieStore.set({
          name: 'partition_test',
          value: data,
          expires: Date.now() + msPerHour,
          sameSite: 'none'
        });
      }

CookieStore.read:
async () => {
        if (!window.cookieStore) {
          throw new Error('Unsupported');
        }
        const cookie = await window.cookieStore.get('partition_test');
        if (!cookie) {
          return null;
        }
        return cookie.value;
      }

