locks.write:
async (key) => {
        if (navigator.locks) {
          navigator.locks.request(key, lock => new Promise((resolve) => {}));
          const queryResult = await navigator.locks.query();
          return queryResult.held[0].clientId;
        } else {
          throw new Error('Unsupported');
        }
      }

locks.read:
async () => {
        if (navigator.locks) {
          const queryResult = await navigator.locks.query();
          return queryResult.held[0].name;
        }
      }

