CookieStore.write:
(data) => {
        const msPerHour = 60 * 60 * 1000;
        if (!window.cookieStore) {
          throw new Error('Unsupported');
        }
        window.cookieStore.set({
          name: 'partition_test',
          value: data,
          expires: Date.now() + msPerHour,
          sameSite: 'none'
        });
      }

CookieStore.read:
async () => {
        if (!window.cookieStore) {
          throw new Error('Unsupported');
        }
        const cookie = await window.cookieStore.get('partition_test');
        if (!cookie) {
          return null;
        }
        return cookie.value;
      }

getDirectory.write:
async (secret) => {
        try {
          const root = await navigator.storage.getDirectory();
          const fileHandle = await root.getFileHandle('secret.txt', { create: true });
          const stream = await fileHandle.createWritable();
          await stream.write(secret);
          await stream.close();
        } catch (e) {
          throw new Error('Unsupported');
        }
      }

getDirectory.read:
async () => {
        try {
          const root = await navigator.storage.getDirectory();
          const fileHandle = await root.getFileHandle('secret.txt');
          const file = await fileHandle.getFile();
          return file.text();
        } catch (e) {
          throw new Error('Unsupported');
        }
      }

