        let newWidth;
        do {
          await sleepMs(100);
          newWidth = text.getBoundingClientRect().width;
        } while (newWidth < 0 || newWidth === originalWidth);
        const response = await fetch(
          testURI('ctr', 'font', key), { cache: 'reload' });
        return (await response.text()).trim();
      }

