Alt-Svc.write:
async () => {
      // Clear Alt-Svc caching first.
        let responseText = '';
        for (let i = 0; i < 3; ++i) {
          await fetch(altSvcOrigin + '/clear');
          await sleepMs(100);
        }
        responseText = await fetchText(altSvcOrigin + '/protocol');
