BroadcastChannel.read:
() =>
        new Promise((resolve, reject) => {
          const bc = new BroadcastChannel('secrets');
          bc.onmessage = (event) => {
            if (event.data !== 'request') {
              resolve(event.data);
            }
          };
          bc.postMessage('request');
          setTimeout(() => reject(new Error('no BroadcastChannel message')), 3000);
        })

