font cache.write:
async (key) => {
        const style = document.createElement('style');
        style.type = 'text/css';
        const fontURI = testURI('resource', 'font', key);
        style.innerHTML = `@font-face {font-family: "myFont"; src: url("${fontURI}"); } body { font-family: "myFont" }`;
