cookie (HTTP).read:
async () => {
      // Test if we now send a requests with a 'cookie' header containing the secret.
        const response = await fetch(`${baseURI}headers`);
        const cookie = (await response.json()).cookie;
        return cookie ? cookie.match(/secret=([\w-]+)/)[1] : null;
      }

